insert into data_vault.municipality_electoral_basis_2027(
  municipality_id,country_code,reference_date,published_population_total,
  population_male,population_female,reconciled_population_total,arithmetic_delta,
  reconciliation_status,population_band,mayor,syndics_titular,syndics_substitute,
  councilors_titular,councilors_substitute,titular_positions,all_positions,
  source_id,source_label,source_status,updated_at
)
select
  m.id,'GT','2026-06-30'::date,i.published_population_total,
  i.population_male,i.population_female,i.reconciled_population_total,i.arithmetic_delta,
  i.reconciliation_status,i.population_band,i.mayor,i.syndics_titular,i.syndics_substitute,
  i.councilors_titular,i.councilors_substitute,i.titular_positions,i.all_positions,
  'GT-TSE-ACUERDO-327-2026','TSE · Acuerdo 327-2026 · base demográfica para corporaciones municipales 2027','VALIDATED',now()
from input i
join public.municipalities m
  on m.country_code='GT' and m.municipality_code=i.municipality_code
on conflict (municipality_id) do update set
  reference_date=excluded.reference_date,
  published_population_total=excluded.published_population_total,
  population_male=excluded.population_male,
  population_female=excluded.population_female,
  reconciled_population_total=excluded.reconciled_population_total,
  arithmetic_delta=excluded.arithmetic_delta,
  reconciliation_status=excluded.reconciliation_status,
  population_band=excluded.population_band,
  mayor=excluded.mayor,
  syndics_titular=excluded.syndics_titular,
  syndics_substitute=excluded.syndics_substitute,
  councilors_titular=excluded.councilors_titular,
  councilors_substitute=excluded.councilors_substitute,
  titular_positions=excluded.titular_positions,
  all_positions=excluded.all_positions,
  source_id=excluded.source_id,
  source_label=excluded.source_label,
  source_status=excluded.source_status,
  updated_at=now();

with basis as (
  select municipality_id,reconciled_population_total,population_male,population_female
  from data_vault.municipality_electoral_basis_2027
)
insert into data_vault.municipality_demographic_aggregates(
  municipality_id,projection_year,reference_date,population_total,population_male,
  population_female,source_product_id,source_label,updated_at
)
select municipality_id,2026,'2026-06-30'::date,reconciled_population_total,
       population_male,population_female,'GT-TSE-ACUERDO-327-2026',
       'TSE · Acuerdo 327-2026 · población adoptada para corporaciones municipales 2027',now()
from basis
on conflict (municipality_id,projection_year,source_product_id) do update set
  reference_date=excluded.reference_date,
  population_total=excluded.population_total,
  population_male=excluded.population_male,
  population_female=excluded.population_female,
  source_label=excluded.source_label,
  updated_at=now();

create or replace function public.radar_authorized_electoral_basis_2027_v1(p_municipality_code text)
returns jsonb
language sql
stable
security invoker
set search_path to 'pg_catalog','public','data_vault','private','pg_temp'
as $function$
  select (to_jsonb(b) - 'municipality_id' - 'created_at' - 'updated_at')
         || jsonb_build_object('municipality_code', m.municipality_code)
  from public.radar_authorized_context_v2('municipality', p_municipality_code) c
  join public.municipalities m
    on m.country_code=c.country_code and m.municipality_code=c.municipality_code
  join data_vault.municipality_electoral_basis_2027 b on b.municipality_id=m.id
  where c.country_code='GT' and c.municipality_code=p_municipality_code
  limit 1;
$function$;

revoke all on function public.radar_authorized_electoral_basis_2027_v1(text) from public, anon;
grant execute on function public.radar_authorized_electoral_basis_2027_v1(text) to authenticated;

create or replace function public.radar_authorized_demographic_summary_v1(p_municipality_code text)
returns jsonb
language sql
stable
security invoker
set search_path = pg_catalog, public, data_vault, private, pg_temp
as $$
  select jsonb_build_object(
    'municipality_code', m.municipality_code,
    'projection_year', d.projection_year,
    'reference_date', d.reference_date,
    'population_total', d.population_total,
    'population_male', d.population_male,
    'population_female', d.population_female,
    'source_product_id', d.source_product_id,
    'source_label', d.source_label
  )
  from public.municipalities m
  join data_vault.municipality_demographic_aggregates d on d.municipality_id=m.id
  where m.country_code='GT'
    and m.municipality_code=p_municipality_code
    and d.projection_year=2026
    and d.source_product_id='GT-TSE-ACUERDO-327-2026'
  limit 1;
$$;

revoke all on function public.radar_authorized_demographic_summary_v1(text) from public, anon;
grant execute on function public.radar_authorized_demographic_summary_v1(text) to authenticated;

update data_vault.municipality_intelligence_profiles_v1 p
set profile = jsonb_set(
      jsonb_set(
        p.profile,
        '{electoral_basis_2027}',
        (to_jsonb(b) - 'municipality_id' - 'created_at' - 'updated_at')
          || jsonb_build_object('municipality_code', m.municipality_code),
        true
      ),
      '{source_manifest,municipal_council_2027}',
      to_jsonb('GT-TSE-ACUERDO-327-2026'::text),
      true
    ),
    source_manifest = jsonb_set(
      p.source_manifest,
      '{municipal_council_2027}',
      to_jsonb('GT-TSE-ACUERDO-327-2026'::text),
      true
    ),
    updated_at = now()
from data_vault.municipality_electoral_basis_2027 b
join public.municipalities m on m.id=b.municipality_id
where b.municipality_id=p.municipality_id;

create or replace function public.radar_authorized_runtime_v8(p_municipality_code text)
returns jsonb
language sql
stable
security invoker
set search_path to 'pg_catalog','public','data_vault','private','campaign_vault','pg_temp'
as $function$
  with base as materialized (
    select public.radar_authorized_runtime_v7(p_municipality_code) as value
  ), profile as materialized (
    select public.radar_authorized_intelligence_profile_v1(p_municipality_code) as value
  ), readiness as materialized (
    select public.radar_authorized_client_readiness_v1(p_municipality_code) as value
  ), electoral_basis as materialized (
    select public.radar_authorized_electoral_basis_2027_v1(p_municipality_code) as value
  )
  select case
    when b.value is null then null
    else jsonb_set(
      jsonb_set(
        jsonb_set(b.value, '{intelligence_profile}', coalesce(p.value, 'null'::jsonb), true),
        '{client_readiness}', coalesce(r.value, 'null'::jsonb), true
      ),
      '{electoral_basis_2027}', coalesce(e.value, 'null'::jsonb), true
    )
  end
  from base b
  cross join profile p
  cross join readiness r
  cross join electoral_basis e;
$function$;

revoke all on function public.radar_authorized_runtime_v8(text) from public, anon;
grant execute on function public.radar_authorized_runtime_v8(text) to authenticated;

do $$
declare
  basis_count integer;
  profile_count integer;
  anomaly_count integer;
begin
  select count(*) into basis_count from data_vault.municipality_electoral_basis_2027;
  select count(*) into profile_count
  from data_vault.municipality_intelligence_profiles_v1
  where profile ? 'electoral_basis_2027';
  select count(*) into anomaly_count
  from data_vault.municipality_electoral_basis_2027
  where reconciliation_status='PUBLISHED_TOTAL_DIFFERS_FROM_SEX_SUM';
  if basis_count <> 340 or profile_count <> 340 or anomaly_count <> 1 then
    raise exception 'Agreement 327 reconciliation failed: basis %, profiles %, anomalies %', basis_count, profile_count, anomaly_count;
  end if;
end $$;

commit;

